css:
.fiscal-sim-container {
    padding: 24px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.fiscal-sim-header {
    background: #1a2744;
    color: #f4f5f7;
    padding: 28px 32px;
    border-bottom: 4px solid #d4a017;
    margin: -24px -24px 28px -24px;
}
.fiscal-sim-header h1 {
    font-size: 1.6rem;
    margin: 0 0 6px 0;
    font-weight: 700;
    letter-spacing: 0.02em;
}
.fiscal-sim-header .fiscal-sim-subtitle {
    font-size: 0.78rem;
    opacity: 0.78;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #8a6710;
}
.fiscal-sim-period-counter {
    background: #ffffff;
    border: 1px solid #d6dae0;
    border-left: 4px solid #1a2744;
    padding: 12px 18px;
    margin-bottom: 22px;
    font-size: 0.85rem;
    color: #4a5568;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.fiscal-sim-period-counter span {
    font-weight: 700;
    color: #1a2744;
}

.fiscal-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
}
.fiscal-sim-status-card {
    background: #ffffff;
    border: 1px solid #d6dae0;
    padding: 16px 18px;
    position: relative;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.fiscal-sim-status-card:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(26,39,68,0.08);
}
.fiscal-sim-status-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 3px; height: 100%;
    background: #1a2744;
}
.fiscal-sim-status-card.accent::before { background: #d4a017; }
.fiscal-sim-status-card.warn::before   { background: #c1272d; }
.fiscal-sim-status-card.good::before   { background: #2d6a4f; }
.fiscal-sim-label {
    font-size: 0.66rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #5f6673;
    margin-bottom: 8px;
    font-weight: 600;
}
.fiscal-sim-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.fiscal-sim-status-card.warn .fiscal-sim-value { color: #c1272d; }
.fiscal-sim-status-card.good .fiscal-sim-value { color: #2d6a4f; }
.fiscal-sim-status-card.accent .fiscal-sim-value { color: #8a6710; }

.fiscal-sim-briefing {
    background: #ffffff;
    border: 1px solid #d6dae0;
    border-left: 4px solid #d4a017;
    padding: 20px 24px;
    margin-bottom: 24px;
    line-height: 1.65;
    font-size: 0.95rem;
    color: #2a3a5a;
}
.fiscal-sim-briefing strong { color: #1a2744; }

.fiscal-sim-controls {
    background: #ffffff;
    border: 1px solid #d6dae0;
    padding: 24px 26px;
    margin-bottom: 22px;
}
.fiscal-sim-controls h3 {
    font-size: 1rem;
    margin: 0 0 18px 0;
    color: #1a2744;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #1a2744;
    padding-bottom: 10px;
}
.fiscal-sim-lever-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-bottom: 14px;
}
.fiscal-sim-lever {
    background: #f8f9fb;
    border: 1px solid #d6dae0;
    border-left: 3px solid #4a5568;
    padding: 12px 14px;
}
.fiscal-sim-lever:nth-child(1) { border-left-color: #8e44ad; }
.fiscal-sim-lever:nth-child(2) { border-left-color: #2980b9; }
.fiscal-sim-lever:nth-child(3) { border-left-color: #2d6a4f; }
.fiscal-sim-lever:nth-child(4) { border-left-color: #d4a017; }
.fiscal-sim-lever:nth-child(5) { border-left-color: #c1272d; }
.fiscal-sim-lever:nth-child(6) { border-left-color: #16798a; }
.fiscal-sim-lever label {
    display: block;
    font-size: 0.78rem;
    color: #2a3a5a;
    margin-bottom: 8px;
    line-height: 1.35;
    font-weight: 600;
}
.fiscal-sim-lever input[type="number"],
.fiscal-sim-controls input[type="number"],
.fiscal-sim-controls select {
    background: #ffffff;
    border: 1px solid #b9bfc8;
    color: #1a2744;
    border-radius: 4px;
    padding: 8px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-weight: 600;
}
.fiscal-sim-lever input[type="number"]:focus,
.fiscal-sim-controls input[type="number"]:focus,
.fiscal-sim-controls select:focus {
    outline: none;
    border-color: #d4a017;
    box-shadow: 0 0 0 2px rgba(212,160,23,0.18);
}
.fiscal-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.fiscal-sim-remaining {
    text-align: right;
    font-weight: 700;
    font-size: 1rem;
    padding: 12px 18px;
    background: #f0f2f5;
    border: 1px solid #d6dae0;
    margin-top: 10px;
    color: #1a2744;
}
.fiscal-sim-controls .form-group {
    margin-bottom: 16px;
}
.fiscal-sim-controls .form-group label {
    display: block;
    font-size: 0.85rem;
    color: #2a3a5a;
    margin-bottom: 8px;
    font-weight: 600;
}
.fiscal-sim-actions {
    display: flex;
    gap: 12px;
    margin-bottom: 24px;
    align-items: center;
}
.fiscal-sim-actions .btn-primary {
    background: #1a2744;
    border: 1px solid #1a2744;
    color: #ffffff;
    padding: 11px 28px;
    font-weight: 700;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.82rem;
    transition: background 0.15s ease;
}
.fiscal-sim-actions .btn-primary:hover {
    background: #d4a017;
    border-color: #d4a017;
    color: #1a2744;
}
.fiscal-sim-actions .btn-outline-secondary {
    color: #4a5568;
    border: 1px solid #b9bfc8;
    background: transparent;
    padding: 10px 20px;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-radius: 4px;
    font-weight: 600;
}
.fiscal-sim-actions .btn-outline-secondary:hover {
    background: #f0f2f5;
}
.fiscal-sim-history {
    background: #ffffff;
    border: 1px solid #d6dae0;
    padding: 20px 24px;
    margin-bottom: 22px;
}
.fiscal-sim-history table {
    width: 100%;
    margin: 0;
    border-collapse: collapse;
}
.fiscal-sim-history th {
    background: #1a2744;
    color: #f4f5f7;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 10px 14px;
    text-align: left;
    font-weight: 700;
}
.fiscal-sim-history td {
    padding: 10px 14px;
    border-top: 1px solid #e2e5ea;
    font-size: 0.9rem;
    color: #2a3a5a;
}
.fiscal-sim-history tr:nth-child(even) td {
    background: #f8f9fb;
}
.fiscal-sim-chart {
    background: #ffffff;
    border: 1px solid #d6dae0;
    padding: 22px 24px;
    height: 380px;
    margin-bottom: 24px;
}
.fiscal-sim-section-hidden {
    display: none;
}
@media (max-width: 768px) {
    .fiscal-sim-lever-grid { grid-template-columns: 1fr; }
    .fiscal-sim-status-cards { grid-template-columns: 1fr 1fr; }
    .fiscal-sim-header { padding: 22px 20px; margin: -24px -24px 22px -24px; }
    .fiscal-sim-header h1 { font-size: 1.3rem; }
    .fiscal-sim-controls { padding: 18px; }
    .fiscal-sim-actions { flex-wrap: wrap; }
}


/* --- EQIL 2026-08-07: focus, motion, completion panel --- */
.fiscal-sim-container :focus-visible,
.fiscal-sim-container select:focus-visible,
.fiscal-sim-container input:focus-visible,
.fiscal-sim-container button:focus-visible {
    outline: 3px solid #1b263b;
    outline-offset: 2px;
    border-radius: 3px;
}
.fiscal-sim-completion {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-left: 6px solid #2d6a4f;
    border-radius: 6px;
    padding: 22px 26px;
    margin: 20px 0;
    color: #1b263b;
}
.fiscal-sim-debrief h3 { margin: 0 0 10px; font-size: 1.15rem; }
.fiscal-sim-debrief-headline { font-size: 1rem; margin-bottom: 14px; }
.fiscal-sim-debrief-list {
    list-style: none; padding: 0; margin: 0 0 14px;
    display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 8px;
}
.fiscal-sim-debrief-list li {
    display: flex; justify-content: space-between; gap: 12px;
    background: #f4f5f7; border: 1px solid #e2e6ee; border-radius: 4px; padding: 8px 12px;
}
.fiscal-sim-debrief-k { color: #5f6673; font-size: 0.82rem; }
.fiscal-sim-debrief-v { font-weight: 700; }
.fiscal-sim-debrief-insights p { margin: 0 0 8px; font-size: 0.9rem; line-height: 1.5; }
@media (prefers-reduced-motion: reduce) {
    .fiscal-sim-container *,
    .fiscal-sim-container *::before,
    .fiscal-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

