        getChartData(state) {
            var ds = (state && state.domainState) || {};
            return {
                pathChart: {
                    labels: this._quarterLabels(),
                    datasets: [
                        { data: ds.unemploymentHistory || [], label: this._t('chart_unemp') },
                        { data: ds.bondYieldHistory    || [], label: this._t('chart_yield') },
                        { data: ds.debtHistory         || [], label: this._t('chart_debt') }
                    ]
                }
            };
        }

        getHint(state, results) {
            var d = state.decisions;
            var round = state.currentPeriod;

            if (round === 2) {
                if ((d.L1 + d.L2) > 20) return window.mySimulation.t('hint_taxheavy');
                if (d.L4 >= 22)         return window.mySimulation.t('hint_infraonly');
                if ((d.L3 + d.L6) < 5)  return window.mySimulation.t('hint_no_progressive');
            }
            if (round === 3) {
                if (d.timing === 'T1') return window.mySimulation.t('hint_frontload_comm');
                if (d.timing === 'T3') return window.mySimulation.t('hint_backload_comm');
            }
            if (round === 4 && results) {
                if (results.avgCredibility < 55) return window.mySimulation.t('hint_lowcred');
            }
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            // the outcome column redraws the note from the round results, so it follows the current language
            return [
                { key: 'period',        label: 'Round',   i18nKey: 'col_round' },
                { key: 'results',       label: 'Outcome', i18nKey: 'col_outcome', formatter: function(r) { return (r && typeof r === 'object') ? self._noteFor(r) : r; } }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var avgMult = ds.weightedMultiplier || 0;
            var jobs    = ds.jobsCreated || 0;
            var unemp   = ds.unemployment || 8.7;
            var debt    = ds.debtToGDP || 62;
            var avgCred = ((ds.credibilityBond || 0) + (ds.credibilityVoter || 0) + (ds.credibilityIMF || 0)) / 3;

            var score = (avgMult * 22)
                      + (Math.max(0, 8.7 - unemp) * 7)
                      + Math.min(28, avgCred * 0.30)
                      - Math.max(0, debt - 65) * 1.5;
            score = Math.max(0, Math.min(100, score));

            var perf = 'beginner';
            if (score >= 78)      perf = 'cabinet_grade';
            else if (score >= 60) perf = 'strong';
            else if (score >= 40) perf = 'adequate';
            var perfKey = 'perf_' + perf;
            var overall = Math.round(score);

            var insights = [];
            if (avgMult >= 1.3) insights.push(window.mySimulation.t('insight_strong_mix'));
            else if (avgMult < 0.9) insights.push(window.mySimulation.t('insight_weak_mix'));
            if (avgCred >= 78) insights.push(window.mySimulation.t('insight_strong_comm'));
            else if (avgCred < 50) insights.push(window.mySimulation.t('insight_weak_comm'));
            if (debt > 70) insights.push(window.mySimulation.t('insight_debt_high'));
            else if (debt < 64) insights.push(window.mySimulation.t('insight_debt_ok'));
            if (unemp < 7.0) insights.push(window.mySimulation.t('insight_unemp_drop'));
            else if (unemp > 8.5) insights.push(window.mySimulation.t('insight_unemp_stuck'));

            return {
                composite:         overall,
                overallScore:      overall,
                totalScore:        overall,
                score:             overall,
                avgMultiplier:     avgMult,
                jobs:              jobs,
                finalUnemployment: unemp,
                finalDebt:         debt,
                avgCredibility:    Math.round(avgCred),
                performance:       perf,
                performanceKey:    perfKey,
                performanceLabel:  this._t(perfKey),
                insights:          insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var t = function(k) { return self._t(k); };
            var esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            var rows = [
                [t('debrief_multiplier'), (s.avgMultiplier || 0).toFixed(2) + 'x'],
                [t('debrief_jobs'), Math.round(s.jobs || 0).toLocaleString()],
                [t('debrief_unemp'), (s.finalUnemployment || 0).toFixed(1) + '%'],
                [t('debrief_debt'), (s.finalDebt || 0).toFixed(1) + '%'],
                [t('debrief_cred'), esc(s.avgCredibility) + '/100']
            ].map(function(r) {
                return '<li><span class="fiscal-sim-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="fiscal-sim-debrief-v">' + esc(r[1]) + '</span></li>';
            }).join('');
            var ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            return '<div class="fiscal-sim-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="fiscal-sim-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="fiscal-sim-debrief-list">' + rows + '</ul>' +
                     '<div class="fiscal-sim-debrief-insights">' + ins + '</div>' +
                   '</div>';
        }

